484:   function handleYouTubeSubmit(event) {
485:     event.preventDefault();
486:     const media = parseYouTubeUrl(ui.url.value);
487:     if (!media) {
488:       ui.playerStatus.textContent = 'Ese link no parece un video o playlist compatible de YouTube.';
489:       ui.url.focus();
490:       return;
491:     }
492:     state.pendingMedia = media;
493:     ui.playerFrame.hidden = false;
494:     ui.playerStatus.textContent = media?.type === 'playlist' ? 'Preparando playlist de YouTube…' : 'Preparando video de YouTube…';
495:     if (state.player) {
496:       try { state.player.destroy(); } catch (_) { /* Ignore stale player cleanup errors. */ }
497:       state.player = null;
498:     }
499:     ui.player.replaceChildren();
500:     loadYouTubeApi();
501:   }
502: 
503:   function parseYouTubeUrl(value) {
504:     const raw = String(value || '').trim();
505:     if (!raw || raw.length > 2048) return null;
506:     let url;
507:     try {
508:       url = new URL(/^[a-z][a-z\d+.-]*:/i.test(raw) ? raw : `https://${raw}`);
509:     } catch (_) {
510:       return null;
511:     }
512:     if (!['https:', 'http:'].includes(url.protocol) || url.username || url.password) return null;
513:     const host = url.hostname.toLowerCase().replace(/\.$/, '');
514:     const isYoutube = host === 'youtube.com' || host.endsWith('.youtube.com');
515:     const isShort = host === 'youtu.be';
516:     if (!isYoutube && !isShort) return null;
517:     const playlistId = url.searchParams.get('list');
518:     const validPlaylist = playlistId && /^[A-Za-z0-9_-]{10,120}$/.test(playlistId);
519:     let videoId = '';
520:     if (isShort) videoId = url.pathname.split('/').filter(Boolean)[0] || '';
521:     else if (url.pathname === '/watch') videoId = url.searchParams.get('v') || '';
522:     else {
523:       const match = url.pathname.match(/^\/(?:embed|shorts|live)\/([A-Za-z0-9_-]{11})(?:\/|$)/);
524:       if (match) videoId = match[1];
525:     }
526:     if (/^[A-Za-z0-9_-]{11}$/.test(videoId)) return { type: 'video', id: videoId };
527:     if (validPlaylist) return { type: 'playlist', id: playlistId };
528:     return null;
529:   }
530: 
531:   function loadYouTubeApi() {
532:     if (window.YT && window.YT.Player) {
533:       createYouTubePlayer();
534:       return;
535:     }
536:     if (state.apiState === 'loading') return;
537:     state.apiState = 'loading';
538:     const previousCallback = window.onYouTubeIframeAPIReady;
539:     window.onYouTubeIframeAPIReady = () => {
540:       if (typeof previousCallback === 'function') {
541:         try { previousCallback(); } catch (_) { /* Do not block this player. */ }
542:       }
543:       state.apiState = 'ready';
544:       createYouTubePlayer();
545:     };
546:     let script = document.querySelector('script[data-rapea-youtube-api]');
547:     if (!script) {
548:       script = document.createElement('script');
549:       script.src = 'https://www.youtube.com/iframe_api';
550:       script.async = true;
551:       script.dataset.rapeaYoutubeApi = 'true';
552:       script.onerror = () => {
553:         state.apiState = 'idle';
554:         ui.playerStatus.textContent = 'No se pudo conectar con YouTube. Podés seguir practicando sin el reproductor.';
555:       };
556:       document.head.append(script);
557:     }
558:     window.setTimeout(() => {
559:       if (state.apiState === 'loading') {
560:         state.apiState = 'idle';
561:         ui.playerStatus.textContent = 'YouTube tarda en responder o está bloqueado. Volvé a cargar el link para reintentar.';
562:       }
563:     }, 12000);
564:   }
565: 
566:   function createYouTubePlayer() {
567:     if (!state.pendingMedia || !window.YT || !window.YT.Player) return;
568:     state.apiState = 'ready';
569:     const media = state.pendingMedia;
570:     try {
571:       state.player = new window.YT.Player(ui.player, {
572:         width: '100%', height: '100%',
573:         playerVars: { autoplay: 0, controls: 1, playsinline: 1, rel: 0 },
574:         events: {
575:           onReady(event) {
576:             if (state.pendingMedia !== media) return;
577:             if (media?.type === 'video') event.target.cueVideoById(media.id);
578:             else if (media?.type === 'playlist') event.target.cuePlaylist({ listType: 'playlist', list: media.id, index: 0 });
579:             else return;
580:             ui.playerStatus.textContent = 'Reproductor listo. Iniciá el video con sus controles; el TAP sigue independiente.';
581:           },
582:           onError(event) {
583:             const messages = {
584:               2: 'YouTube rechazó el identificador del video o playlist.',
585:               5: 'Este video no se puede reproducir en el reproductor HTML5.',
586:               100: 'El video no existe o no está disponible.',
587:               101: 'El dueño del video no permite reproducirlo en este reproductor.',
588:               150: 'El dueño del video no permite reproducirlo en este reproductor.',
589:               153: 'YouTube no pudo validar esta solicitud. Probá desde un sitio publicado.',
590:             };
591:             ui.playerStatus.textContent = messages[event.data] || 'YouTube no pudo cargar ese contenido; probá otro link.';
592:           },
593:         },
594:       });
595:       ui.playerStatus.textContent = 'Conectando con el reproductor oficial de YouTube…';
596:     } catch (_) {
597:       state.player = null;
598:       ui.playerStatus.textContent = 'No se pudo iniciar YouTube en este navegador. El entrenamiento sigue disponible.';
599:     }
600:   }
601: 
602:   function closeYouTubePlayer() {
603:     if (state.player) {
604:       try { state.player.destroy(); } catch (_) { /* Ignore stale player cleanup errors. */ }
605:     }
606:     state.player = null;
607:     state.pendingMedia = null;
608:     ui.player.replaceChildren();
609:     ui.playerFrame.hidden = true;
610:     ui.playerStatus.textContent = 'El beat suena por YouTube; el TAP marca un metrónomo independiente.';
611:   }
612: })();

